package br.gov.dere.application.csv;
import br.gov.dere.application.d1001.D1001XmlGenerator; import br.gov.dere.domain.contributor.D1001; import br.gov.dere.integration.xml.XmlSupport; import java.time.LocalDate;
public class DereCsvConverter { public D1001 fromCsv(String csv){var lines=csv.lines().filter(s->!s.isBlank()).toList();var names=lines.get(0).split(",",-1);var values=lines.get(1).split(",",-1);var h=new java.util.HashMap<String,Integer>();for(int i=0;i<names.length;i++)h.put(names[i].trim(),i);java.util.function.Function<String,String> get=n->{var i=h.get(n);return i==null||i>=values.length?"":values[i].trim();};return new D1001(get.apply("id"),Integer.parseInt(get.apply("tpOper")),Integer.parseInt(get.apply("tpAmb")),get.apply("verAplic"),get.apply("nrInsc"),LocalDate.parse(get.apply("iniValid")),get.apply("fimValid").isBlank()?null:LocalDate.parse(get.apply("fimValid")),Integer.parseInt(get.apply("regTribPrinc")),get.apply("regTribSecund").isBlank()?java.util.List.of():java.util.Arrays.stream(get.apply("regTribSecund").split(";")).map(Integer::parseInt).toList(),Integer.parseInt(get.apply("indNatTrib")));} public String toCsv(D1001 d){return "id,motExcl,nrProc,tpOper,tpAmb,aplicEmi,verAplic,nrInsc,iniValid,fimValid,novaValidadeIniValid,novaValidadeFimValid,regTribPrinc,regTribSecund,indNatTrib,tpAtividadeServFinanc,tpAtividadePlAssistSaude,tpAtividadePrognosticos,UFCredenc\n"+String.join(",",d.id(),"","", ""+d.operation(),""+d.environment(),"1",d.applicationVersion(),d.cnpjRoot(),d.validFrom().toString(),d.validTo()==null?"":d.validTo().toString(),"","",""+d.primaryTaxRegime(),d.secondaryTaxRegimes().stream().map(String::valueOf).collect(java.util.stream.Collectors.joining(";")),""+d.taxNature(),"","","","");} public String xmlToCsv(String xml)throws Exception{var d=XmlSupport.parse(xml);var e=(org.w3c.dom.Element)d.getElementsByTagNameNS(D1001XmlGenerator.NS,"evtInfoContrib").item(0);java.util.function.Function<String,String> text=n->{var x=(org.w3c.dom.Element)e.getElementsByTagNameNS(D1001XmlGenerator.NS,n).item(0);return x==null?"":x.getTextContent();};return "id,motExcl,nrProc,tpOper,tpAmb,aplicEmi,verAplic,nrInsc,iniValid,fimValid,novaValidadeIniValid,novaValidadeFimValid,regTribPrinc,regTribSecund,indNatTrib,tpAtividadeServFinanc,tpAtividadePlAssistSaude,tpAtividadePrognosticos,UFCredenc\n"+String.join(",",e.getAttribute("id"),"","",text.apply("tpOper"),text.apply("tpAmb"),text.apply("aplicEmi"),text.apply("verAplic"),text.apply("nrInsc"),text.apply("iniValid"),text.apply("fimValid"),"","",text.apply("regTribPrinc"),text.apply("regTribSecund"),text.apply("indNatTrib"),"","","","");}}
